// src/pages/HomePage.jsx
// Senior UI/UX Redesign - Luxury Cycling E-Commerce (Canyon, Trek & Specialized Spec)
// Ten: Le Thanh Ho | MSSV: 2123110125 | Lop: CCQ2311D

import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { motion, useScroll, useTransform } from "framer-motion";
import { 
  ArrowRight, 
  Bike, 
  ShieldCheck, 
  Wrench, 
  Truck, 
  Zap, 
  Star, 
  Mail, 
  ChevronRight, 
  Sparkles, 
  TrendingUp, 
  Flame, 
  MessageSquare, 
  Newspaper 
} from "lucide-react";

import productService from "../services/productService";
import categoryService from "../services/categoryService";
import postService from "../services/postService";
import reviewService from "../services/reviewService";
import bannerService from "../services/bannerService";
import ProductCard from "../components/ProductCard";
import Loader from "../components/Loader";
import { resolveImageUrl } from "../components/ProductCard";

// 🎯 1. COMPONENT LUXURY HERO SCREEN WITH PARALLAX EFFECT
function LuxuryHero({ banners, loadingBanners }) {
  const [index, setIndex] = useState(0);
  const { scrollY } = useScroll();

  // Tạo hiệu ứng Parallax mượt mà khi cuộn màn hình như website Canyon
  const yBg = useTransform(scrollY, [0, 500], [0, 150]);
  const opacityText = useTransform(scrollY, [0, 300], [1, 0]);

  useEffect(() => {
    if (banners.length <= 1) return;
    const timer = setInterval(() => setIndex((i) => (i + 1) % banners.length), 6000);
    return () => clearInterval(timer);
  }, [banners]);

  if (loadingBanners || banners.length === 0) {
    return (
      <div className="h-screen bg-[#0F172A] flex items-center justify-center text-white/30">
        <Loader small />
      </div>
    );
  }

  const currentSlide = banners[index];

  return (
    <section className="relative w-full h-screen bg-[#0b0f19] flex items-center overflow-hidden select-none">
      {/* Parallax Background Cover Image */}
      <motion.div style={{ y: yBg }} className="absolute inset-0 w-full h-full z-0">
        <img
          src={resolveImageUrl(currentSlide.image)}
          alt={currentSlide.title}
          className="w-full h-full object-cover opacity-45 scale-102 transition-all duration-1000"
        />
        <div className="absolute inset-0 bg-gradient-to-r from-[#0b0f19] via-[#0b0f19]/70 to-transparent" />
        <div className="absolute inset-0 bg-gradient-to-t from-[#0b0f19] via-transparent to-transparent" />
      </motion.div>

      {/* Grid Pattern Line Decoration */}
      <div className="absolute inset-0 opacity-[0.02] bg-[linear-gradient(to_right,#fff_1px,transparent_1px),linear-gradient(to_bottom,#fff_1px,transparent_1px)] bg-[size:4rem_4.rem] z-10 pointer-events-none" />

      {/* Floating Content Area */}
      <div className="max-w-7xl mx-auto px-6 md:px-8 w-full relative z-20">
        <motion.div style={{ opacity: opacityText }} className="max-w-2xl space-y-6">
          <div className="inline-flex items-center gap-2 bg-white/5 border border-white/10 backdrop-blur-md px-3 py-1.5 rounded-full text-[10px] font-bold text-[#C9FF3D] uppercase tracking-widest">
            <Sparkles className="w-3.5 h-3.5 animate-pulse" /> Pure Racing Engineering
          </div>
          <h1 className="font-sans font-black text-5xl md:text-7xl text-white tracking-tighter leading-[0.95]">
            {currentSlide.title.split(" ").map((word, i) => (
              <span key={i} className={word.includes(".") ? "text-[#C9FF3D]" : ""}>{word} </span>
            ))}
          </h1>
          <p className="text-gray-400 text-sm md:text-base max-w-md font-medium leading-relaxed">
            Trải nghiệm các dòng xe đạp hiệu suất cao được chế tác từ sợi carbon nguyên khối, nhập khẩu trực tiếp từ các đường đua thế giới.
          </p>
          {currentSlide.link && (
            <div className="pt-4">
              <Link
                to={currentSlide.link}
                className="inline-flex items-center gap-3 bg-[#C9FF3D] hover:bg-white text-[#0B0F19] font-black text-xs uppercase tracking-wider px-8 py-4 rounded-xl transition-all duration-300 shadow-xl shadow-[#C9FF3D]/10 group active:scale-95"
              >
                Khám phá ngay <ArrowRight className="w-4 h-4 transition-transform group-hover:translate-x-1" />
              </Link>
            </div>
          )}
        </motion.div>
      </div>

      {/* Slider Bullets Navigation */}
      {banners.length > 1 && (
        <div className="absolute bottom-12 left-6 md:left-8 z-30 flex items-center gap-3">
          {banners.map((_, i) => (
            <button
              key={i}
              onClick={() => setIndex(i)}
              className={`h-1 rounded-full transition-all duration-500 ${i === index ? "bg-[#C9FF3D] w-12" : "bg-white/20 w-4 hover:bg-white/40"}`}
            />
          ))}
        </div>
      )}
    </section>
  );
}

// 🎯 2. COMPONENT FLASH SALE COUNTDOWN ZONE
function FlashSaleSection({ products }) {
  const [timeLeft, setTimeLeft] = useState({ hours: 14, minutes: 32, seconds: 45 });

  useEffect(() => {
    const timer = setInterval(() => {
      setTimeLeft(prev => {
        if (prev.seconds > 0) return { ...prev, seconds: prev.seconds - 1 };
        if (prev.minutes > 0) return { ...prev, minutes: prev.minutes - 1, seconds: 55 };
        if (prev.hours > 0) return { hours: prev.hours - 1, minutes: 55, seconds: 55 };
        return prev;
      });
    }, 1000);
    return () => clearInterval(timer);
  }, []);

  if (products.length === 0) return null;

  return (
    <section className="max-w-7xl mx-auto px-6 md:px-8 py-12 relative z-10">
      <div className="bg-gradient-to-r from-red-600 to-rose-700 rounded-3xl p-6 md:p-8 shadow-xl relative overflow-hidden flex flex-col lg:flex-row lg:items-center justify-between gap-6">
        <div className="space-y-2 relative z-10">
          <div className="inline-flex items-center gap-1.5 bg-white/10 border border-white/20 rounded-lg px-2.5 py-1 text-[10px] font-bold text-white uppercase tracking-wider">
            <Zap className="w-3 h-3 fill-white" /> Limited Offer
          </div>
          <h2 className="text-2xl md:text-3xl font-black tracking-tight text-white">FLASH SALE CHỚP NHOÁNG</h2>
          <p className="text-white/80 text-xs font-medium">Cơ hội sở hữu siêu xe Specialized & Canyon với mức giá đặc quyền.</p>
        </div>

        {/* Countdown UI Elements */}
        <div className="flex items-center gap-3 relative z-10 font-mono text-white">
          <div className="flex flex-col items-center bg-black/20 backdrop-blur-md border border-white/10 rounded-xl px-4 py-3 min-w-[65px] shadow-inner">
            <span className="text-xl md:text-2xl font-black">{String(timeLeft.hours).padStart(2, "0")}</span>
            <span className="text-[9px] font-sans font-bold uppercase tracking-wider opacity-60 mt-0.5">Giờ</span>
          </div>
          <span className="text-xl font-bold animate-pulse">:</span>
          <div className="flex flex-col items-center bg-black/20 backdrop-blur-md border border-white/10 rounded-xl px-4 py-3 min-w-[65px] shadow-inner">
            <span className="text-xl md:text-2xl font-black">{String(timeLeft.minutes).padStart(2, "0")}</span>
            <span className="text-[9px] font-sans font-bold uppercase tracking-wider opacity-60 mt-0.5">Phút</span>
          </div>
          <span className="text-xl font-bold animate-pulse">:</span>
          <div className="flex flex-col items-center bg-black/20 backdrop-blur-md border border-white/10 rounded-xl px-4 py-3 min-w-[65px] shadow-inner">
            <span className="text-xl md:text-2xl font-black">{String(timeLeft.seconds).padStart(2, "0")}</span>
            <span className="text-[9px] font-sans font-bold uppercase tracking-wider opacity-60 mt-0.5">Giây</span>
          </div>
        </div>
      </div>
    </section>
  );
}

// 🎯 3. MAIN HOMEPAGE COMPONENT (REFACTOR UI/UX, KEEP GỐC 100% DATA LOGIC)
export default function HomePage() {
  const [banners, setBanners] = useState([]);
  const [featured, setFeatured] = useState([]);
  const [bestSellers, setBestSellers] = useState([]);
  const [newest, setNewest] = useState([]);
  const [categories, setCategories] = useState([]);
  const [posts, setPosts] = useState([]);
  const [testimonials, setTestimonials] = useState([]);
  const [loading, setLoading] = useState(true);
  const [loadingBanners, setLoadingBanners] = useState(true);

  useEffect(() => {
    const load = async () => {
      try {
        setLoading(true);
        // GIỮ NGUYÊN LUỒNG CALL API PROMISE.ALL TỐC ĐỘ CAO CỦA HỒ
        const [f, b, n, c, p, t, bn] = await Promise.all([
          productService.getFeatured(),
          productService.getBestSellers(),
          productService.getNewest(),
          categoryService.getAll(),
          postService.getPublished(),
          reviewService.getTestimonials(),
          bannerService.getActive(),
        ]);
        setFeatured(f.data || []);
        setBestSellers(b.data || []);
        setNewest(n.data || []);
        setCategories(c.data || []);
        setPosts(p.data?.slice(0, 3) || []);
        setTestimonials(t.data || []);
        setBanners(bn.data || []);
      } catch (err) {
        console.error("Lỗi fetch API trang chủ:", err);
      } finally {
        setLoading(false);
        setLoadingBanners(false);
      }
    };
    load();
  }, []);

  return (
